<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,allPages} from '../services/api';import {usePage} from '../services/usePage';import {useAuth} from '../stores/auth';import Notice from '../components/Notice.vue'
const auth=useAuth(),profile=ref({first_name:auth.user?.first_name||'',last_name:auth.user?.last_name||'',email:auth.user?.email||'',password:''}),users=ref<any[]>([]),form=ref({username:'',email:'',password:'',role:'researcher'});const {error,success,busy,act}=usePage();onMounted(()=>{if(auth.user?.administrator)act(async()=>{users.value=await allPages('users/')})})
const save=()=>act(async()=>{const data:any={...profile.value};if(!data.password)delete data.password;auth.user=(await api.patch('users/me/',data)).data;profile.value.password=''},'Perfil actualizado.')
const create=()=>act(async()=>{await api.post('users/',form.value);users.value=await allPages('users/');form.value={username:'',email:'',password:'',role:'researcher'}},'Usuario creado.')
const update=(u:any)=>act(async()=>{await api.patch(`users/${u.id}/`,{role:u.role,is_active:u.is_active})},'Permisos actualizados.')
</script>
<template><h1 class="heading">Tu espacio de trabajo</h1><p class="subheading mb-7">Perfil y gestión de acceso al laboratorio.</p><Notice :error="error" :success="success"/><form class="card mb-6 max-w-3xl" @submit.prevent="save"><h2 class="mb-5 font-semibold">Mi perfil</h2><div class="grid gap-4 md:grid-cols-2"><div v-for="(label,key) in {first_name:'Nombres',last_name:'Apellidos',email:'Correo',password:'Nueva contraseña (opcional)'}" :key="key"><label class="label">{{label}}</label><input v-model="profile[key]" class="input" :type="key==='password'?'password':key==='email'?'email':'text'" :autocomplete="key==='password'?'new-password':'off'"/></div></div><button class="btn mt-5" :disabled="busy">Guardar cambios</button></form><template v-if="auth.user?.administrator"><form class="card mb-6" @submit.prevent="create"><h2 class="mb-5 font-semibold">Crear usuario</h2><div class="grid gap-4 md:grid-cols-4"><input v-model="form.username" class="input" required placeholder="Usuario"/><input v-model="form.email" class="input" type="email" placeholder="Correo"/><input v-model="form.password" class="input" type="password" required placeholder="Contraseña inicial" autocomplete="new-password"/><select v-model="form.role" class="input"><option value="researcher">Investigador</option><option value="admin">Administrador</option></select></div><button class="btn mt-4" :disabled="busy">Crear cuenta</button></form><div class="table-wrap bg-white"><table class="data-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Activo</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}</td><td><select v-model="u.role" class="input" :disabled="u.id===auth.user.id"><option value="researcher">Investigador</option><option value="admin">Administrador</option></select></td><td><input v-model="u.is_active" type="checkbox" :disabled="u.id===auth.user.id"/></td><td><button class="btn-secondary" :disabled="busy||u.id===auth.user.id" @click="update(u)">Guardar</button></td></tr></tbody></table></div></template><p class="mt-6 text-xs text-slate-500">La sesión se mantiene en memoria por seguridad. Al recargar la aplicación deberás iniciar sesión nuevamente.</p></template>
